3. Nahrung und Kollisionsprüfung: Um Nahrung in das Spielfeld zu bringen, erstellen wir eine weitere Struktur und eine Funktion, die prüft, ob die Schlange mit der Nahrung kollidiert:

```c
typedef struct {
    int x, y;
} Food;

Food food;

bool is_food_collided(void) {
    return (snake[0].x == food.x && snake[0].y == food.y);
}

void generate_food(void) {
    food.x = rand() % BOARD_SIZE;
    food.y = rand() % BOARD_SIZE;
    while (board[food.x][food.y] != 0) {
        food.x = rand() % BOARD_SIZE;
        food.y = rand() % BOARD_SIZE;
    }
    board[food.x][food.y] = 1;
}
```

4. Spiellogik: Die Spiellogik beinhaltet das Verarbeiten von Ereignissen, die Bewegung der Schlange, das Wachstum der Schlange und das Ende des Spiels:

```c
enum {
    DIRECTION_UP,
    DIRECTION_RIGHT,
    DIRECTION_DOWN,
    DIRECTION_LEFT
};

int direction = DIRECTION_RIGHT;

void handle_input(void) {
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        switch (event.type) {
            case SDL_QUIT:
                running = false;
                break;
            case SDL_KEYDOWN:
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        if (direction != DIRECTION_DOWN)
                            direction = DIRECTION_UP;
                        break;
                    case SDLK_RIGHT:
                        if (direction != DIRECTION_LEFT)
                            direction = DIRECTION_RIGHT;
                        break;
                    case SDLK_DOWN:
                        if (direction != DIRECTION_UP)
                            direction = DIRECTION_DOWN;
                        break;
                    case SDLK_LEFT:
                        if (direction != DIRECTION_RIGHT)
                            direction = DIRECTION_LEFT;
                        break;
                }
                break;
        }
    }
}

void move_snake(void) {
    for (int I = snake_len - 1; I > 0; i--) {
        snake[i].x = snake[i - 1].x;
        snake[i].y = snake[i - 1].y;
    }

    switch (direction) {
        case DIRECTION_UP:
            snake[0].y--;
            break;
        case DIRECTION_RIGHT:
            snake[0].x++;
            break;
        case DIRECTION_DOWN:
            snake[0].y++;
            break;
        case DIRECTION_LEFT:
            snake[0].x--;
            break;
    }

    if (snake[0].x < 0 || snake[0].x >= BOARD_SIZE || snake[0].y < 0 || snake[0].y >= BOARD_SIZE ||
        board[snake[0].x][snake[0].y] == 2) {
        running = false;
    } else if (is_food_collided()) {
        snake_len++;
        board[food.x][food.y] = 0;
        generate_food();
    } else {
        board[snake[snake_len - 1].x][snake[snake_len - 1].y] = 0;
    }
}
```

5. Rendering: Um die Spielfeld- und Schlange-Animation zu rendern, erstellen wir eine Funktion, die das Spielfeld und die Schlange zeichnet:

```c
void render_board(void) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
    SDL_RenderClear(renderer);

    for (int I = 0; I < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[i][j] == 1) {
                SDL_Rect rect = {
                    i * (640 / BOARD_SIZE),
                    j * (640 / BOARD_SIZE),
                    (i + 1) * (640 / BOARD_SIZE),
                    (j + 1) * (640 / BOARD_SIZE)
                };
                SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
                SDL_RenderFillRect(renderer, &rect);
            }
            if (board[i][j] == 2) {
                SDL_Rect rect = {
                    i * (640 / BOARD_SIZE),
                    j * (640 / BOARD_SIZE),
                    (i + 1) * (640 / BOARD_SIZE),
                    (j + 1) * (640 / BOARD_SIZE)
                };
                SDL_SetRenderDrawColor(renderer, 255, 0, 0, 255);
                SDL_RenderFillRect(renderer, &rect);
            }
        }
    }

    for (int I = 1; I < snake_len; i++) {
        SDL_Rect rect = {
            snake[i].x * (640 / BOARD_SIZE),
            snake[i].y * (640 / BOARD_SIZE),
            (snake[i].x + 1) * (640 / BOARD_SIZE),
            (snake[i].y + 1) * (640 / BOARD_SIZE)
        };
        SDL_SetRenderDrawColor(renderer, 0, 255, 0, 255);
        SDL_RenderFillRect(renderer, &rect);
    }

    SDL_Rect rect = {
        snake[0].x * (640 / BOARD_SIZE),
        snake[0].y * (640 / BOARD_SIZE),
        (snake[0].x + 1) * (640 / BOARD_SIZE),
        (snake[0].y + 1) * (640 / BOARD_SIZE)
    };
    SDL_SetRenderDrawColor(renderer, 0, 0, 255, 255);
    SDL_RenderFillRect(renderer, &rect);
}
```

6. Game Loop: Schließlich bringen wir alles zusammen und starten den Game Loop:

```c
int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);
    SDL_Window* window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        640, 640,
        SDL_WINDOW_SHOWN
    );
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    srand(time(NULL));

    board[snake_head_x][snake_head_y] = 2;

    bool running = true;
    while (running) {
        handle_input();
        move_snake();
        render_board();
        SDL_RenderPresent(renderer);
        SDL_Delay(100);
    }

    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
```

Dies ist eine sehr grobe Vorstellung des Snake Games mit SDL, die einige Komponenten auslässt, wie z.B. Soundeffekte, Score und Highscore. Um das Spiel weiter zu verbessern und zu erweitern, können Sie diese und weitere Features hinzufügen.

