    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] < arr2[j]) {
            i++;
        } else if (arr1[i] > arr2[j]) {
            j++;
        } else {
            indices1.add(i);
            indices2.add(j);
            i++;
            j++;
        }
    }

    int[] common = new int[Math.min(indices1.size(), indices2.size())];
    int k = 0;

    for (int I = 0; I < indices1.size(); i++) {
        if (i < indices1.size() && I == indices2.get(indices2.indexOf(indices1.get(i)))) {
            common[k] = arr1[indices1.get(i)];
            k++;
        }
    }

    if (k == common.length) {
        return common;
    } else {
        return Arrays.copyOf(common, k);
    }
